func TestPayloadTypeGenerationBoundaries(t *testing.T) {
	program, err := language.Compile(payloadTargetContract)
	if err != nil {
		t.Fatal(err)
	}
	for _, targets := range []map[string]string{{"": "Int"}, {string([]byte{0xff}): "Int"}, {"bad": "Box"}, {"bad": "Box a"}, {"bad": "Int -> Int"}, {"bad": "Int where it"}, {"valid": "Box Age", "bad": "Unknown"}} {
		if files, err := GenerateValidatorWithTypes(program, "example", "Contract", targets); err == nil || files != nil {
			t.Fatalf("partial or unchecked targets: %v", err)
		}
	}
	specs := payloadTargetSpecs()
	first, err := GenerateValidatorWithTypes(program, "example", "Contract", specs)
	if err != nil {
		t.Fatal(err)
	}
	second, err := GenerateValidatorWithTypes(program, "example", "Contract", specs)
	if err != nil || !slices.Equal(first, second) {
		t.Fatalf("nondeterministic targets: %v", err)
	}
	plain, err := GenerateValidator(program, "example", "Contract")
	if err != nil {
		t.Fatal(err)
	}
	empty, err := GenerateValidatorWithTypes(program, "example", "Contract", map[string]string{})
	if err != nil || !slices.Equal(plain, empty) {
		t.Fatal("default generator changed semantics")
	}
	// A large registry and a contract class named like the generated handle
	// must still produce compilable, executable static metadata.
	compiler, vm := javaTools(t)
	wide := map[string]string{}
	for i := 0; i < 1100; i++ {
		wide[fmt.Sprintf("target%d", i)] = "Age"
	}
	files, err := GenerateValidatorWithTypes(program, "", "PayloadType", wide)
	if err != nil {
		t.Fatal(err)
	}
	root := t.TempDir()
	sources := []string{}
	for _, file := range files {
		target := filepath.Join(root, file.Path)
		if err := os.WriteFile(target, []byte(file.Source), 0644); err != nil {
			t.Fatal(err)
		}
		sources = append(sources, target)
	}
	target := filepath.Join(root, "Use.java")
	source := `public final class Use { public static void main(String[] args) {
        for(int i=0;i<1100;i++){
            var target=PayloadType.payloadType("target"+i);
            if(target.validate(new Data.Number(Rational.of(1))).state()!=Validation.State.VALID)throw new AssertionError();
            if(target.read("-1").data()!=null)throw new AssertionError();
        }
    } }`
	if err := os.WriteFile(target, []byte(source), 0644); err != nil {
		t.Fatal(err)
	}
	sources = append(sources, target)
	classes := filepath.Join(root, "classes")
	args := append([]string{"--release", "25", "-encoding", "UTF-8", "-Xlint:all", "-Werror", "-d", classes}, sources...)
	if output, err := exec.Command(compiler, args...).CombinedOutput(); err != nil {
		t.Fatalf("wide targets: %v\n%s", err, output)
	}
	if output, err := exec.Command(vm, "-Xss256k", "-cp", classes, "Use").CombinedOutput(); err != nil {
		t.Fatalf("wide target execution: %v\n%s", err, output)
	}
}

func FuzzPayloadTypeGeneration(f *testing.F) {
	for _, source := range payloadTargetSpecs() {
		f.Add(source)
	}
	program, err := language.Compile(payloadTargetContract)
	if err != nil {
		f.Fatal(err)
	}
	f.Fuzz(func(t *testing.T, source string) {
		if len(source) > 4096 {
			return
		}
		specs := map[string]string{"target": source}
		first, err := GenerateValidatorWithTypes(program, "example", "Contract", specs)
		second, again := GenerateValidatorWithTypes(program, "example", "Contract", specs)
		if err != nil {
			if first != nil || second != nil || again == nil {
				t.Fatal("partial or nondeterministic failure")
			}
			return
		}
		if again != nil || !slices.Equal(first, second) {
			t.Fatalf("nondeterministic generation: %v", again)
		}
	})
}
